window.__votdWeek && window.__votdWeek({"week":"2026-11-30","reading":"Micah; Nahum; Habakkuk; Zephaniah","days":[{"d":"2026-11-30","ref":"Micah 3:6","b":"Micah","c":3,"v":6,"he":"לָכֵן לַיְלָה לָכֶם מֵחָזוֹן וְחָשְׁכָה לָכֶם מִקְּסֹם וּבָאָה הַשֶּׁמֶשׁ עַל־הַנְּבִיאִים וְקָדַר עֲלֵיהֶם הַיּוֹם׃","en":"Therefore night shall be unto you, that ye shall not have a vision; and it shall be dark unto you, that ye shall not divine; and the sun shall go down over the prophets, and the day shall be dark over them."},{"d":"2026-12-01","ref":"Micah 3:8","b":"Micah","c":3,"v":8,"he":"וְאוּלָם אָנֹכִי מָלֵאתִי כֹחַ אֶת־רוּחַ יְהֹוָה וּמִשְׁפָּט וּגְבוּרָה לְהַגִּיד לְיַעֲקֹב פִּשְׁעוֹ וּלְיִשְׂרָאֵל חַטָּאתוֹ׃","en":"But truly I am full of power by the spirit of the LORD, and of judgment, and of might, to declare unto Jacob his transgression, and to Israel his sin."},{"d":"2026-12-02","ref":"Micah 4:7","b":"Micah","c":4,"v":7,"he":"וְשַׂמְתִּי אֶת־הַצֹּלֵעָה לִשְׁאֵרִית וְהַנַּהֲלָאָה לְגוֹי עָצוּם וּמָלַךְ יְהֹוָה עֲלֵיהֶם בְּהַר צִיּוֹן מֵעַתָּה וְעַד־עוֹלָם׃","en":"And I will make her that halted a remnant, and her that was cast far off a strong nation: and the LORD shall reign over them in mount Zion from henceforth, even for ever."},{"d":"2026-12-03","ref":"Micah 5:5","b":"Micah","c":5,"v":4,"he":"וְהָיָה זֶה שָׁלוֹם אַשּׁוּר כִּי־יָבוֹא בְאַרְצֵנוּ וְכִי יִדְרֹךְ בְּאַרְמְנוֹתֵינוּ וַהֲקֵמֹנוּ עָלָיו שִׁבְעָה רֹעִים וּשְׁמֹנָה נְסִיכֵי אָדָם׃","en":"And this man shall be the peace, when the Assyrian shall come into our land: and when he shall tread in our palaces, then shall we raise against him seven shepherds, and eight principal men."},{"d":"2026-12-04","ref":"Micah 6:8","b":"Micah","c":6,"v":8,"he":"הִגִּיד לְךָ אָדָם מַה־טּוֹב וּמָה־יְהֹוָה דּוֹרֵשׁ מִמְּךָ כִּי אִם־עֲשׂוֹת מִשְׁפָּט וְאַהֲבַת חֶסֶד וְהַצְנֵעַ לֶכֶת עִם־אֱלֹהֶיךָ׃","en":"He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?"},{"d":"2026-12-05","ref":"Nahum 1:15","b":"Nahum","c":2,"v":1,"he":"הִנֵּה עַל־הֶהָרִים רַגְלֵי מְבַשֵּׂר מַשְׁמִיעַ שָׁלוֹם חׇגִּי יְהוּדָה חַגַּיִךְ שַׁלְּמִי נְדָרָיִךְ כִּי לֹא יוֹסִיף עוֹד [לַעֲבׇר־]בָּךְ בְּלִיַּעַל כֻּלֹּה נִכְרָת׃","en":"Behold upon the mountains the feet of him that bringeth good tidings, that publisheth peace! O Judah, keep thy solemn feasts, perform thy vows: for the wicked shall no more pass through thee; he is utterly cut off."},{"d":"2026-12-06","ref":"Habakkuk 2:4","b":"Habakkuk","c":2,"v":4,"he":"הִנֵּה עֻפְּלָה לֹא־יׇשְׁרָה נַפְשׁוֹ בּוֹ וְצַדִּיק בֶּאֱמוּנָתוֹ יִחְיֶה׃","en":"Behold, his soul which is lifted up is not upright in him: but the just shall live by his faith."}]});
